import React, { useState, useEffect } from "react";
import Login from "./components/login";
import IncomeCategory from "./components/IncomeCategory";
import SpendingPriority from "./components/SpendingPriority";
import BudgetLimits from "./components/BudgetLimits";
import Dashboard from "./components/Dashboard";
import Questionnaire from "./components/Questionnaire";

function App() {
  const [step, setStep] = useState("login");

  const [data, setData] = useState({
    income: "",
    questionnaire: {},
    categories: [],
    priorities: [],
    limits: {}
  });

  // ✅ LOAD EXISTING USER
  useEffect(() => {
    const savedUser = JSON.parse(localStorage.getItem("userData"));

    if (savedUser) {
      setData(savedUser);
      setStep("dashboard"); // 🔥 SKIP ALL PAGES
    }
  }, []);

  // ✅ SAVE USER DATA EVERY CHANGE
  const updateData = (newData) => {
    const updated = { ...data, ...newData };
    setData(updated);
    localStorage.setItem("userData", JSON.stringify(updated));
  };

  return (
    <>
      {step === "login" && (
        <Login onLogin={() => setStep("income")} />
      )}

      {step === "income" && (
        <IncomeCategory
          onNext={(val) => {
            updateData({ income: val });
            setStep("questionnaire");
          }}
        />
      )}

      {step === "questionnaire" && (
        <Questionnaire
          onNext={(answers) => {
            updateData({ questionnaire: answers });
            setStep("priority");
          }}
          onBack={() => setStep("income")}
        />
      )}

      {step === "priority" && (
        <SpendingPriority
          onNext={(priorities) => {
            updateData({ priorities });
            setStep("budget");
          }}
          onBack={() => setStep("questionnaire")}
        />
      )}

      {step === "budget" && (
        <BudgetLimits
          selectedCategories={data.priorities}
          onNext={(limits) => {
            updateData({ limits });
            setStep("dashboard");
          }}
          onBack={() => setStep("priority")}
        />
      )}

      {step === "dashboard" && (
        <Dashboard userData={data} updateUserData={updateData} />
      )}
    </>
  );
}

export default App;
